from 写入第二遍 import add
add('05_002',8,'16:9，越武士背肩的全景，巨大背与上臂占画面右侧近层，青全身缩在左后；从武士腰侧缓移半步，维持双方纵深距离。','武士把肩头向后缓缓张开，双臂略离躯干，在近处形成厚重外框；青在远处直起一点，双手空着垂在身侧。武士催她拿出真本事，尾句拖住“犄角”的话头，青的下巴缓缓下收，双肩不再随怒气上顶，目光停在巨大的背肩轮廓。','灰绿石铺地面在两人间形成长条空隙，远端平台横边外接蓝灰云天与米灰薄尘。','正上方云天冷白柔光，武士背面是较暗冷灰，远处青衣色与银发清楚。','武士缓慢呼吸，风卷小颗石屑在两人之间擦过地面。',ja=['…少しは本気を出せ。','その程度では、甲角竜の角を切り落とせたはずがない。'],tone='第一句低沉催促，第二句带试探与嘲弄，语尾稳稳压向青。',kind='mixed',phase='state',meaning='越巨大武士背肩看远处青，两句均由武士说出。',characters=['鬼头武士','青'],card={'opening':'武士逼青公开实力。','beats':['肩背张开占据近处','远处青由怒目转为下收下巴衡量'],'coupling':'武士说话持续占据画幅，青微小的身体反应在远处发生。','landing':'青停止顶撞，开始权衡代价。'})
add('05_003',3,'16:9，低机位武士胸肩与头部中近景，宽肩横占下幅，狭长眼裂在中央上方；慢慢推近到白眼清楚。','武士肩颈向上挺，胸廓撑开，白眼在裂隙里直盯青；他把最后一句说得缓慢，句尾头部略偏，像等对手交出答案。肩部挺起后停住，只剩胸口起伏。','宽肩上缘留蓝灰云天，云层向右缓移，平台不入画。','冷白云天漫射在肩顶形成宽亮面，胸廓下侧为冷灰。','低沉气息与厚重关节一声轻响，风声越过肩头。',ja=['失望させるなよ…'],tone='低声催逼，尾句向下沉，留一拍等待。',kind='mixed',phase='state',meaning='武士挺胸、白眼盯视与最后催逼台词保留。',characters=['鬼头武士'],card={'opening':'试探后武士收成最后通牒。','beats':['挺肩撑胸、白眼定住','头略偏，拖低尾句'],'coupling':'话落才停住挺身，让庞大身形压住等待。','landing':'把回应空间交给青。'})
add('05_004',10,'16:9，青双眼的横向极特写，眉与闭合眼睑占画面中央，左侧耳尖与发根只留一线；固定机位缓慢靠近，嘴始终在画外。','青合紧双眼，眉心先收成短褶，再稍稍松开；呼吸从急促慢成一口长气。内心想到那一招时眼睑微颤，想到接管战场的空缺，眉心又压紧，眼睛仍闭着，额角汗珠滑到画幅下缘。','两侧发隙只有均匀浅蓝灰天空，细小云纹模糊为柔面。','上方冷白漫射很软地覆盖额头，睫毛下缘细灰影稳定。','一口延长的呼吸，远处平台风声与细碎石屑滚声。',ja=['…私だって、あの技を使いたい。','でも今「玉石倶焚」を使ったら、その後、戦場を引き継げる人がいなくなる…！'],tone='内心第一句压着冲动，第二句逐字衡量后果，末尾焦急但声音留在心里。',kind='mixed',phase='state',meaning='闭眼衡量禁招；本镜只在思考，尚未发动。',characters=['青'],card={'opening':'青从挑衅中收回注意，开始算后果。','beats':['闭眼长呼气，眉尖稍松','想到无人接手又蹙紧，汗珠滑落'],'coupling':'每次眉间变化承接内心的条件与结论，嘴保持画外。','landing':'冲动被责任压住，仍未下决心。'})
